//! The G-code file header per Moonraker printer (`mica_gcode_identity`). Upstream Moonraker
//! reads the metadata (thumbnails, time, filament) of any slicer that writes
//! `; generated by NAME VERSION on …`; older forks, such as the one in Snapmaker's U1
//! firmware, only know a fixed slicer list and report Mica's files as `slicer: Unknown`.
//!
//! Automatic starts from the profile's default. After each upload to a Moonraker printer the
//! upload thread reads `/server/files/metadata` for the file (read-only); when the printer
//! calls a file with Mica's own header `Unknown`, that printer's later files use the
//! Orca-compatible header, once, with a notification. The chosen header feeds the slice
//! configuration like `mica slice --gcode-identity`, so GUI and CLI output stay identical.

use super::config::FileHeader;
use super::job::SlicerReport;
use crate::app::App;

/// The notification when Automatic switches a printer to the Orca-compatible header.
pub const SWITCHED: &str = "This printer's firmware doesn't recognize Mica Slicer files; future \
                            files use an Orca-compatible header so it shows thumbnails and times";

impl App {
    /// The `mica_gcode_identity` the linked printer asks for (`None`: the profile decides).
    pub(crate) fn printer_gcode_identity(&self) -> Option<&'static str> {
        let i = self.linked_printer()?;
        self.printers.list.get(i)?.gcode_identity()
    }

    /// Takes in what the upload threads learned (see `job::SlicerReport`).
    pub(crate) fn check_file_identity(&mut self) {
        let reports: Vec<SlicerReport> =
            std::iter::from_fn(|| self.identity_reports.1.try_recv().ok()).collect();
        for r in reports {
            self.apply_slicer_report(&r);
        }
        // The linked printer (or its header) changed in My printers: slice with the new one.
        if self.printer_gcode_identity() != self.applied_identity {
            self.settings_changed();
        }
    }

    /// One report: a printer on Automatic that calls a Mica-header file `Unknown` switches to
    /// the Orca-compatible header for future files. Returns whether it switched.
    pub(crate) fn apply_slicer_report(&mut self, r: &SlicerReport) -> bool {
        let Some(i) = self.printers.position(r.printer) else {
            return false;
        };
        let before = self.printer_gcode_identity();
        let p = &mut self.printers.list[i];
        let unknown = r.slicer.trim().eq_ignore_ascii_case("unknown");
        if !p.is_moonraker()
            || p.file_header.is_some()
            || r.identity != "mica"
            || !unknown
            || p.file_header_detected == Some(FileHeader::OrcaCompatible)
        {
            return false;
        }
        p.file_header_detected = Some(FileHeader::OrcaCompatible);
        let name = p.name.clone();
        self.printers.dirty = true;
        if let Err(e) = self.printers.save() {
            self.notify_error(
                format!("Could not save the printer settings: {e}"),
                format!("Could not save the File header setting of {name}: {e}"),
            );
        }
        self.notify_info(format!("{name}: {SWITCHED}"));
        if self.printer_gcode_identity() != before {
            self.settings_changed();
        }
        true
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::printhost::config::{Kind, Printer};

    #[test]
    fn identity_per_printer_kind_and_choice() {
        let mut p = Printer::new(Kind::SnapmakerU1);
        assert_eq!(p.gcode_identity(), None, "Automatic: the profile decides");
        p.file_header_detected = Some(FileHeader::OrcaCompatible);
        assert_eq!(p.gcode_identity(), Some("orca_compatible"));
        p.file_header = Some(FileHeader::Mica);
        assert_eq!(p.gcode_identity(), Some("mica"), "a choice beats detection");
        let mut link = Printer::new(Kind::PrusaLink);
        link.file_header = Some(FileHeader::OrcaCompatible);
        assert_eq!(link.gcode_identity(), None, "Moonraker printers only");
    }
}
